const CATEGORIES = [{"id": "be", "name": "To be", "level": "Foundation", "rule": "Use am with I, is with he/she/it, and are with you/we/they.", "questions": [{"prompt": "I ___ thirteen years old.", "answer": "am", "options": ["am", "is", "are"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}, {"prompt": "The children ___ in the playground.", "answer": "are", "options": ["are", "is", "am"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}, {"prompt": "My bicycle ___ blue.", "answer": "is", "options": ["is", "are", "am"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}, {"prompt": "Sue and Ellen ___ sisters.", "answer": "are", "options": ["are", "is", "am"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}, {"prompt": "___ the tree tall?", "answer": "Is", "options": ["Is", "Are", "Am"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}, {"prompt": "We ___ not at school today.", "answer": "are", "options": ["are", "is", "am"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}, {"prompt": "My grandma is ill. ___ at the doctor’s.", "answer": "She’s", "options": ["She’s", "He’s", "They’re"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}, {"prompt": "My sister and I are at home. ___ alone.", "answer": "We’re", "options": ["We’re", "They’re", "I’m"], "explanation": "Use am with I, is with he/she/it, and are with you/we/they."}], "sources": [{"name": "Grammar_ToBe_18873__sz.pdf", "url": "worksheets/Grammar_ToBe_18873__sz.pdf"}]}, {"id": "have", "name": "Have got", "level": "Foundation", "rule": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject.", "questions": [{"prompt": "She ___ a new bicycle.", "answer": "has got", "options": ["has got", "have got", "is got"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}, {"prompt": "I ___ a present for you.", "answer": "have got", "options": ["have got", "has got", "am got"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}, {"prompt": "___ you got a pencil?", "answer": "Have", "options": ["Have", "Has", "Are"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}, {"prompt": "The dog ___ a little house.", "answer": "has got", "options": ["has got", "have got", "are got"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}, {"prompt": "They ___ any tickets. (negative)", "answer": "haven’t got", "options": ["haven’t got", "hasn’t got", "aren’t got"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}, {"prompt": "___ the captain got a map?", "answer": "Has", "options": ["Has", "Have", "Is"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}, {"prompt": "We ___ a good idea.", "answer": "have got", "options": ["have got", "has got", "is got"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}, {"prompt": "He hasn’t ___ a watch.", "answer": "got", "options": ["got", "get", "gets"], "explanation": "Use have got with I/you/we/they and has got with he/she/it. In questions, put have/has before the subject."}], "sources": [{"name": "Grammar_HaveGot_18831__sz.pdf", "url": "worksheets/Grammar_HaveGot_18831__sz.pdf"}]}, {"id": "be-have", "name": "To be & have got", "level": "Foundation", "rule": "Use be for age, identity and descriptions. Use have/has got for possession.", "questions": [{"prompt": "Jean ___ from America.", "answer": "is", "options": ["is", "has got", "are"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}, {"prompt": "Mike and I ___ brothers.", "answer": "are", "options": ["are", "have got", "is"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}, {"prompt": "The school ___ new computers.", "answer": "has got", "options": ["has got", "is", "have got"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}, {"prompt": "I ___ in the kitchen.", "answer": "am", "options": ["am", "have got", "is"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}, {"prompt": "You and your sister ___ many books.", "answer": "have got", "options": ["have got", "has got", "are"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}, {"prompt": "___ you eleven years old?", "answer": "Are", "options": ["Are", "Have", "Has"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}, {"prompt": "The dog ___ a little house.", "answer": "has got", "options": ["has got", "is", "have got"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}, {"prompt": "We ___ not afraid of dogs.", "answer": "are", "options": ["are", "have", "has"], "explanation": "Use be for age, identity and descriptions. Use have/has got for possession."}], "sources": [{"name": "Grammar_ToBeHaveGot1_18874__sz.pdf", "url": "worksheets/Grammar_ToBeHaveGot1_18874__sz.pdf"}, {"name": "Grammar_ToBeHaveGot2_18875__sz.pdf", "url": "worksheets/Grammar_ToBeHaveGot2_18875__sz.pdf"}]}, {"id": "articles", "name": "Articles, plurals & nouns", "level": "Foundation", "rule": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives.", "questions": [{"prompt": "I have ___ egg for breakfast.", "answer": "an", "options": ["an", "a", "the some"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}, {"prompt": "Alan has got a dog. ___ dog is brown.", "answer": "The", "options": ["The", "A", "An"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}, {"prompt": "My sister is ___ dentist.", "answer": "a", "options": ["a", "an", "any"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}, {"prompt": "There aren’t ___ evil characters in the play.", "answer": "any", "options": ["any", "some", "a"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}, {"prompt": "I’d like ___ spaghetti for dinner.", "answer": "some", "options": ["some", "any", "an"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}, {"prompt": "What is the plural of “tooth”?", "answer": "teeth", "options": ["teeth", "tooths", "toothes"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}, {"prompt": "What is the plural of “story”?", "answer": "stories", "options": ["stories", "storys", "storyes"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}, {"prompt": "Which noun is uncountable?", "answer": "water", "options": ["water", "egg", "chair"], "explanation": "Use a before consonant sounds and an before vowel sounds. Use the for an identified noun. Some is usual in affirmatives; any in questions and negatives."}], "sources": [{"name": "Grammar_AAnThe_18820__sz.pdf", "url": "worksheets/Grammar_AAnThe_18820__sz.pdf"}]}, {"id": "possessives", "name": "Possessives, this & that", "level": "Foundation", "rule": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural.", "questions": [{"prompt": "This book belongs to me. It is ___.", "answer": "mine", "options": ["mine", "my", "me"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}, {"prompt": "That is ___ bag. (she)", "answer": "her", "options": ["her", "hers", "she"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}, {"prompt": "These are the ___ toys. (one boy)", "answer": "boy’s", "options": ["boy’s", "boys’", "boys"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}, {"prompt": "___ is my friend here beside me.", "answer": "This", "options": ["This", "These", "Those"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}, {"prompt": "___ are our books over there.", "answer": "Those", "options": ["Those", "That", "This"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}, {"prompt": "We own this house. It is ___.", "answer": "ours", "options": ["ours", "our", "us"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}, {"prompt": "This is ___ coat. (Tom)", "answer": "Tom’s", "options": ["Tom’s", "Toms", "Tom"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}, {"prompt": "The cat is washing ___ face.", "answer": "its", "options": ["its", "it’s", "it"], "explanation": "Use possessive adjectives before nouns, possessive pronouns alone, and ’s for ownership. This/that are singular; these/those are plural."}], "sources": [{"name": "Grammar_PosessiveFormsThisThat_18848__sz.pdf", "url": "worksheets/Grammar_PosessiveFormsThisThat_18848__sz.pdf"}]}, {"id": "there", "name": "There is, there are & quantifiers", "level": "Foundation", "rule": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns.", "questions": [{"prompt": "___ a glass on the table.", "answer": "There is", "options": ["There is", "There are", "There have"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}, {"prompt": "___ six desks for the pupils.", "answer": "There are", "options": ["There are", "There is", "There has"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}, {"prompt": "How ___ students are in your class?", "answer": "many", "options": ["many", "much", "a little"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}, {"prompt": "There isn’t ___ sugar in my tea.", "answer": "much", "options": ["much", "many", "a few"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}, {"prompt": "There are a ___ things to do.", "answer": "few", "options": ["few", "little", "much"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}, {"prompt": "There is a ___ ketchup in the bottle.", "answer": "little", "options": ["little", "few", "many"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}, {"prompt": "Are there any ___ in the park?", "answer": "children", "options": ["children", "child", "childs"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}, {"prompt": "There aren’t ___ chairs for everyone.", "answer": "any", "options": ["any", "some", "a"], "explanation": "Use there is with singular and uncountable nouns, there are with plurals. Many/a few go with countable plurals; much/a little with uncountable nouns."}], "sources": [{"name": "Grammar_ThereIsThereAreQuantifiers1_18869__sz.pdf", "url": "worksheets/Grammar_ThereIsThereAreQuantifiers1_18869__sz.pdf"}, {"name": "Grammar_ThereIsThereAreQuantifiers2_18870__sz.pdf", "url": "worksheets/Grammar_ThereIsThereAreQuantifiers2_18870__sz.pdf"}, {"name": "Grammar_ThereIsThereAreQuantifires3_18871__sz.pdf", "url": "worksheets/Grammar_ThereIsThereAreQuantifires3_18871__sz.pdf"}]}, {"id": "present-simple", "name": "Present simple", "level": "Foundation", "rule": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives.", "questions": [{"prompt": "She ___ tennis every Saturday.", "answer": "plays", "options": ["plays", "play", "playing"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}, {"prompt": "___ your brother live in London?", "answer": "Does", "options": ["Does", "Do", "Is"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}, {"prompt": "I ___ like coffee.", "answer": "don’t", "options": ["don’t", "doesn’t", "am not"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}, {"prompt": "The sun ___ in the east.", "answer": "rises", "options": ["rises", "rise", "rising"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}, {"prompt": "They ___ to school by bus.", "answer": "go", "options": ["go", "goes", "going"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}, {"prompt": "He ___ his homework every day.", "answer": "does", "options": ["does", "do", "doing"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}, {"prompt": "___ you speak Italian?", "answer": "Do", "options": ["Do", "Does", "Are"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}, {"prompt": "My mum ___ work on Sundays.", "answer": "doesn’t", "options": ["doesn’t", "don’t", "isn’t"], "explanation": "Use the present simple for habits and facts. Add -s/-es for he/she/it; use do/does for questions and don’t/doesn’t for negatives."}], "sources": [{"name": "Grammar_PresentSimple1_18853__sz.pdf", "url": "worksheets/Grammar_PresentSimple1_18853__sz.pdf"}, {"name": "Grammar_PresentSimple2_18854__sz.pdf", "url": "worksheets/Grammar_PresentSimple2_18854__sz.pdf"}, {"name": "Grammar_PresentSimple3_18855__sz.pdf", "url": "worksheets/Grammar_PresentSimple3_18855__sz.pdf"}]}, {"id": "present-cont", "name": "Present continuous", "level": "Foundation", "rule": "Form the present continuous with am/is/are + verb-ing for actions happening now.", "questions": [{"prompt": "Look! The children ___ football.", "answer": "are playing", "options": ["are playing", "plays", "is playing"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}, {"prompt": "I ___ my homework right now.", "answer": "am doing", "options": ["am doing", "do", "does"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}, {"prompt": "___ she watching TV?", "answer": "Is", "options": ["Is", "Does", "Are"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}, {"prompt": "They ___ sleeping at the moment. (negative)", "answer": "aren’t", "options": ["aren’t", "isn’t", "don’t"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}, {"prompt": "We ___ for the bus now.", "answer": "are waiting", "options": ["are waiting", "waits", "is waiting"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}, {"prompt": "Listen! A bird ___ singing.", "answer": "is", "options": ["is", "are", "does"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}, {"prompt": "What ___ you doing now?", "answer": "are", "options": ["are", "is", "do"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}, {"prompt": "He is ___ dinner.", "answer": "making", "options": ["making", "make", "makes"], "explanation": "Form the present continuous with am/is/are + verb-ing for actions happening now."}], "sources": [{"name": "Grammar_PresentContinuous2_18850__sz.pdf", "url": "worksheets/Grammar_PresentContinuous2_18850__sz.pdf"}]}, {"id": "present-mix", "name": "Present simple vs continuous", "level": "Developing", "rule": "Use the present simple for routines and the present continuous for actions happening now or temporary situations.", "questions": [{"prompt": "Usually I walk, but today I ___ the bus.", "answer": "am taking", "options": ["am taking", "take", "takes"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}, {"prompt": "She ___ TV every evening.", "answer": "watches", "options": ["watches", "is watching", "watch"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}, {"prompt": "Listen! The baby ___.", "answer": "is crying", "options": ["is crying", "cries", "cry"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}, {"prompt": "We ___ lunch at one every day.", "answer": "have", "options": ["have", "are having", "has"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}, {"prompt": "He can’t come to the phone. He ___.", "answer": "is cooking", "options": ["is cooking", "cooks", "cook"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}, {"prompt": "My dad ___ in a bank. It’s his regular job.", "answer": "works", "options": ["works", "is work", "work"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}, {"prompt": "They ___ football now.", "answer": "aren’t playing", "options": ["aren’t playing", "don’t play", "doesn’t play"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}, {"prompt": "___ you usually get up early?", "answer": "Do", "options": ["Do", "Are", "Is"], "explanation": "Use the present simple for routines and the present continuous for actions happening now or temporary situations."}], "sources": [{"name": "Grammar_PresSimplePresContinuous1_18858__sz.pdf", "url": "worksheets/Grammar_PresSimplePresContinuous1_18858__sz.pdf"}, {"name": "Grammar_PresSimplePresContinuous2_18859__sz.pdf", "url": "worksheets/Grammar_PresSimplePresContinuous2_18859__sz.pdf"}]}, {"id": "timetables", "name": "Present simple for future timetables", "level": "Developing", "rule": "Use the present simple for scheduled future events such as train departures, flight times and opening hours.", "questions": [{"prompt": "According to the timetable, the train ___ at six tomorrow.", "answer": "leaves", "options": ["leaves", "leave", "leaving"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}, {"prompt": "What time ___ the flight land tomorrow?", "answer": "does", "options": ["does", "is", "do"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}, {"prompt": "The shop ___ at nine tomorrow morning.", "answer": "opens", "options": ["opens", "opening", "open"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}, {"prompt": "Our next lesson ___ at ten.", "answer": "starts", "options": ["starts", "start", "starting"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}, {"prompt": "The scheduled ferry ___ on Sunday.", "answer": "doesn’t sail", "options": ["doesn’t sail", "don’t sail", "not sails"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}, {"prompt": "___ the museum close at five tomorrow?", "answer": "Does", "options": ["Does", "Do", "Are"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}, {"prompt": "The programme ___ at eight tonight, according to the listing.", "answer": "begins", "options": ["begins", "begin", "beginning"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}, {"prompt": "When ___ the buses leave tomorrow?", "answer": "do", "options": ["do", "does", "is"], "explanation": "Use the present simple for scheduled future events such as train departures, flight times and opening hours."}], "sources": [{"name": "Grammar_PresentSimpleFutureMeaning_18856__sz.pdf", "url": "worksheets/Grammar_PresentSimpleFutureMeaning_18856__sz.pdf"}]}, {"id": "past-be", "name": "Was, were & there was/were", "level": "Foundation", "rule": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural.", "questions": [{"prompt": "I ___ at home last night.", "answer": "was", "options": ["was", "were", "am"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}, {"prompt": "Where ___ you yesterday?", "answer": "were", "options": ["were", "was", "are"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}, {"prompt": "___ many people at the party.", "answer": "There were", "options": ["There were", "There was", "There is"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}, {"prompt": "The film ___ interesting yesterday.", "answer": "was", "options": ["was", "were", "is"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}, {"prompt": "___ there a shop here before?", "answer": "Was", "options": ["Was", "Were", "Are"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}, {"prompt": "They ___ at school yesterday. (negative)", "answer": "weren’t", "options": ["weren’t", "wasn’t", "isn’t"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}, {"prompt": "___ two boats in the harbour last night.", "answer": "There were", "options": ["There were", "There was", "There are"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}, {"prompt": "She ___ tired after the trip.", "answer": "was", "options": ["was", "were", "are"], "explanation": "Use was with I/he/she/it and were with you/we/they. There was is singular; there were is plural."}], "sources": [{"name": "Grammar_PastToBeThereWasThereWere_18847__sz.pdf", "url": "worksheets/Grammar_PastToBeThereWasThereWere_18847__sz.pdf"}]}, {"id": "past-simple", "name": "Past simple", "level": "Foundation", "rule": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went.", "questions": [{"prompt": "Yesterday, he ___ at home.", "answer": "stayed", "options": ["stayed", "stay", "stays"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}, {"prompt": "What is the past simple of “go”?", "answer": "went", "options": ["went", "goed", "gone"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}, {"prompt": "Peter didn’t ___ to the library yesterday.", "answer": "go", "options": ["go", "went", "gone"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}, {"prompt": "___ you see the film last night?", "answer": "Did", "options": ["Did", "Do", "Were"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}, {"prompt": "She ___ the doctor yesterday.", "answer": "called", "options": ["called", "calls", "call"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}, {"prompt": "We ___ anything we liked. (not find)", "answer": "didn’t find", "options": ["didn’t find", "didn’t found", "don’t found"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}, {"prompt": "What is the past simple of “eat”?", "answer": "ate", "options": ["ate", "eated", "eaten"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}, {"prompt": "The lesson ___ five minutes ago.", "answer": "began", "options": ["began", "begin", "begun"], "explanation": "Use past simple for finished past events. After did/didn’t, use the base verb. Learn irregular forms such as go → went."}], "sources": [{"name": "Grammar_PastSimple1_18842__sz.pdf", "url": "worksheets/Grammar_PastSimple1_18842__sz.pdf"}, {"name": "Grammar_PastSimple2_18843__sz.pdf", "url": "worksheets/Grammar_PastSimple2_18843__sz.pdf"}, {"name": "Grammar_PastSimple3_18844__sz.pdf", "url": "worksheets/Grammar_PastSimple3_18844__sz.pdf"}]}, {"id": "past-cont", "name": "Past continuous", "level": "Developing", "rule": "Use was/were + verb-ing for actions in progress at a time in the past.", "questions": [{"prompt": "It ___ raining when I got up.", "answer": "was", "options": ["was", "were", "is"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}, {"prompt": "My parents ___ sleeping when the phone rang.", "answer": "were", "options": ["were", "was", "are"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}, {"prompt": "___ you watching TV at six last night?", "answer": "Were", "options": ["Were", "Was", "Did"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}, {"prompt": "I ___ to school when I saw my friend.", "answer": "was walking", "options": ["was walking", "were walking", "walk"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}, {"prompt": "The baby ___ sleeping when we went to bed. (negative)", "answer": "wasn’t", "options": ["wasn’t", "weren’t", "didn’t"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}, {"prompt": "What ___ he doing at midnight?", "answer": "was", "options": ["was", "were", "did"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}, {"prompt": "The boys ___ football at five yesterday.", "answer": "were playing", "options": ["were playing", "was playing", "play"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}, {"prompt": "When I phoned, she ___ supper.", "answer": "was eating", "options": ["was eating", "were eating", "eat"], "explanation": "Use was/were + verb-ing for actions in progress at a time in the past."}], "sources": [{"name": "Grammar_PastContinuous1_18839__sz.pdf", "url": "worksheets/Grammar_PastContinuous1_18839__sz.pdf"}, {"name": "Grammar_PastContinuous2_18840__sz.pdf", "url": "worksheets/Grammar_PastContinuous2_18840__sz.pdf"}]}, {"id": "past-mix", "name": "Past simple vs continuous", "level": "Developing", "rule": "Use past continuous for a background action and past simple for a completed event that interrupts it.", "questions": [{"prompt": "The sun ___ when I looked out of the window.", "answer": "was shining", "options": ["was shining", "shine", "were shining"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}, {"prompt": "While we were eating, the phone ___.", "answer": "rang", "options": ["rang", "was ring", "ring"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}, {"prompt": "I ___ my friend while I was walking home.", "answer": "saw", "options": ["saw", "was see", "seen"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}, {"prompt": "They ___ TV when the lights went out.", "answer": "were watching", "options": ["were watching", "watched now", "was watching"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}, {"prompt": "While he ___, he dropped a plate.", "answer": "was cooking", "options": ["was cooking", "cook", "were cooking"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}, {"prompt": "We ___ for our friends an hour ago. (finished action)", "answer": "waited", "options": ["waited", "waiting", "wait"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}, {"prompt": "What were you doing when I ___?", "answer": "called", "options": ["called", "was call", "calling"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}, {"prompt": "She was reading when her brother ___ home.", "answer": "came", "options": ["came", "was come", "coming"], "explanation": "Use past continuous for a background action and past simple for a completed event that interrupts it."}], "sources": [{"name": "Grammar_PastSimplePastContinuous1_18845__sz.pdf", "url": "worksheets/Grammar_PastSimplePastContinuous1_18845__sz.pdf"}, {"name": "Grammar_PastSimplePastContinuous2_18846__sz.pdf", "url": "worksheets/Grammar_PastSimplePastContinuous2_18846__sz.pdf"}]}, {"id": "past-perfect", "name": "Past perfect simple", "level": "Developing", "rule": "Form the past perfect with had + past participle for an action completed before another past event.", "questions": [{"prompt": "By ten o’clock, the police ___ the thief.", "answer": "had caught", "options": ["had caught", "has caught", "had catch"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}, {"prompt": "The concert ___ before we got to the park.", "answer": "had begun", "options": ["had begun", "has began", "had begin"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}, {"prompt": "She showed me the pictures she ___ last summer.", "answer": "had taken", "options": ["had taken", "had took", "has take"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}, {"prompt": "He ___ for years before he became a doctor.", "answer": "had studied", "options": ["had studied", "has studied", "had study"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}, {"prompt": "We failed because we ___ for the test.", "answer": "hadn’t studied", "options": ["hadn’t studied", "haven’t study", "hadn’t study"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}, {"prompt": "The plane ___ by the time we got to the airport.", "answer": "had landed", "options": ["had landed", "has landed", "had land"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}, {"prompt": "They went home after they ___ to him.", "answer": "had spoken", "options": ["had spoken", "had spoke", "have spoken"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}, {"prompt": "Debbie found the key I ___.", "answer": "had lost", "options": ["had lost", "had lose", "have lost"], "explanation": "Form the past perfect with had + past participle for an action completed before another past event."}], "sources": [{"name": "Grammar_PastPerfectSimple_18841__sz.pdf", "url": "worksheets/Grammar_PastPerfectSimple_18841__sz.pdf"}]}, {"id": "present-perfect", "name": "Present perfect", "level": "Developing", "rule": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives.", "questions": [{"prompt": "She ___ already finished her homework.", "answer": "has", "options": ["has", "have", "is"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}, {"prompt": "I have never ___ to Paris.", "answer": "been", "options": ["been", "was", "be"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}, {"prompt": "We have lived here ___ 2020.", "answer": "since", "options": ["since", "for", "during"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}, {"prompt": "They have known each other ___ five years.", "answer": "for", "options": ["for", "since", "from"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}, {"prompt": "Have you eaten lunch ___?", "answer": "yet", "options": ["yet", "yesterday", "ago"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}, {"prompt": "He hasn’t ___ his keys.", "answer": "found", "options": ["found", "find", "finded"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}, {"prompt": "I ___ that film yesterday. (finished past time)", "answer": "saw", "options": ["saw", "have seen", "has seen"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}, {"prompt": "We ___ just arrived.", "answer": "have", "options": ["have", "has", "are"], "explanation": "Form the present perfect with have/has + past participle. Use since for a starting point and for for a duration; yet commonly appears in questions and negatives."}], "sources": [{"name": "Grammar_PresentPerfect1_18851__sz.pdf", "url": "worksheets/Grammar_PresentPerfect1_18851__sz.pdf"}, {"name": "Grammar_PresentPerfect2_18852__sz.pdf", "url": "worksheets/Grammar_PresentPerfect2_18852__sz.pdf"}]}, {"id": "going-to", "name": "Going to & future arrangements", "level": "Foundation", "rule": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement.", "questions": [{"prompt": "I ___ a new watch soon. (plan)", "answer": "am going to buy", "options": ["am going to buy", "going buy", "am going buy"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}, {"prompt": "We ___ at a restaurant tonight. (plan)", "answer": "are going to eat", "options": ["are going to eat", "is going to eat", "going eating"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}, {"prompt": "Paul ___ basketball later. (plan)", "answer": "is going to play", "options": ["is going to play", "are going to play", "going to plays"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}, {"prompt": "___ you going to study tonight?", "answer": "Are", "options": ["Are", "Do", "Is"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}, {"prompt": "My mum ___ going to work this week. (negative)", "answer": "isn’t", "options": ["isn’t", "aren’t", "doesn’t"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}, {"prompt": "Look at those clouds! It ___ rain.", "answer": "is going to", "options": ["is going to", "are going to", "going"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}, {"prompt": "We have booked tickets. We ___ to London tomorrow.", "answer": "are flying", "options": ["are flying", "flying", "flies"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}, {"prompt": "What are you going to ___ this afternoon?", "answer": "do", "options": ["do", "doing", "does"], "explanation": "Use am/is/are going to + base verb for plans or predictions based on evidence. Present continuous can describe a fixed future arrangement."}], "sources": [{"name": "Grammar_BeGoingTo1_18821__sz.pdf", "url": "worksheets/Grammar_BeGoingTo1_18821__sz.pdf"}, {"name": "Grammar_BeGoingTo2_18822__sz.pdf", "url": "worksheets/Grammar_BeGoingTo2_18822__sz.pdf"}]}, {"id": "will", "name": "Future with will", "level": "Foundation", "rule": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t.", "questions": [{"prompt": "I think it ___ rain tomorrow.", "answer": "will", "options": ["will", "is", "does"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}, {"prompt": "I promise I ___ help you.", "answer": "will", "options": ["will", "am", "do"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}, {"prompt": "She will ___ home soon.", "answer": "come", "options": ["come", "comes", "coming"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}, {"prompt": "We ___ be late. (negative)", "answer": "won’t", "options": ["won’t", "don’t", "aren’t"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}, {"prompt": "___ you help me, please?", "answer": "Will", "options": ["Will", "Are", "Does"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}, {"prompt": "“I’m cold.” “I ___ close the window.”", "answer": "will", "options": ["will", "am", "do"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}, {"prompt": "He ___ be sixteen next year.", "answer": "will", "options": ["will", "is", "does"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}, {"prompt": "They will not ___ the game.", "answer": "win", "options": ["win", "wins", "winning"], "explanation": "Use will + base verb for predictions, offers, promises and spontaneous decisions. The negative is won’t."}], "sources": [{"name": "Grammar_FutureWill_18830__sz.pdf", "url": "worksheets/Grammar_FutureWill_18830__sz.pdf"}]}, {"id": "future-mix", "name": "Future tenses", "level": "Developing", "rule": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events.", "questions": [{"prompt": "Our team has arranged a match. It ___ later.", "answer": "is playing", "options": ["is playing", "playing", "play"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}, {"prompt": "“I’ve left my bag.” “I ___ get it for you.”", "answer": "will", "options": ["will", "am going", "am"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}, {"prompt": "Look! That glass is falling. It ___ break.", "answer": "is going to", "options": ["is going to", "are going to", "going"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}, {"prompt": "We have booked a table. We ___ dinner there tonight.", "answer": "are having", "options": ["are having", "has", "having"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}, {"prompt": "I’m sure you ___ enjoy the trip.", "answer": "will", "options": ["will", "are", "do"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}, {"prompt": "She has decided: she ___ study medicine.", "answer": "is going to", "options": ["is going to", "are going to", "going"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}, {"prompt": "___ your friends coming to the party on Friday?", "answer": "Are", "options": ["Are", "Do", "Is"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}, {"prompt": "We ___ at the airport at six. It’s arranged.", "answer": "are meeting", "options": ["are meeting", "meets", "meeting"], "explanation": "Use will for spontaneous decisions and predictions, going to for intentions or present evidence, and present continuous for arranged future events."}], "sources": [{"name": "Grammar_FutureTenses_18829__sz.pdf", "url": "worksheets/Grammar_FutureTenses_18829__sz.pdf"}]}, {"id": "comparison", "name": "Comparatives & superlatives", "level": "Foundation", "rule": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best.", "questions": [{"prompt": "An elephant is ___ a kangaroo. (strong)", "answer": "stronger than", "options": ["stronger than", "strongest than", "more strong"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}, {"prompt": "Jane’s hair is ___ yours. (long)", "answer": "longer than", "options": ["longer than", "longest than", "long than"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}, {"prompt": "John’s work is ___ Mary’s. (good)", "answer": "better than", "options": ["better than", "gooder than", "best than"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}, {"prompt": "February is ___ month of the year. (short)", "answer": "the shortest", "options": ["the shortest", "shorter than", "most short"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}, {"prompt": "This book is ___ that one. (interesting)", "answer": "more interesting than", "options": ["more interesting than", "interestinger than", "most interesting"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}, {"prompt": "Which is ___ car in the world? (fast)", "answer": "the fastest", "options": ["the fastest", "faster than", "most fast"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}, {"prompt": "An elephant is ___ a lion. (heavy)", "answer": "heavier than", "options": ["heavier than", "heavyer than", "heaviest"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}, {"prompt": "She got ___ mark in the class. (bad)", "answer": "the worst", "options": ["the worst", "the baddest", "worse than"], "explanation": "Use comparative + than to compare two things and the superlative for one in a group. Some forms are irregular: good → better → best."}], "sources": [{"name": "Grammar_ComparisonAdjectives1_18823__sz.pdf", "url": "worksheets/Grammar_ComparisonAdjectives1_18823__sz.pdf"}, {"name": "Grammar_ComparisonAdjectives2_18824__sz.pdf", "url": "worksheets/Grammar_ComparisonAdjectives2_18824__sz.pdf"}]}, {"id": "enough", "name": "As…as, too & enough", "level": "Developing", "rule": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun.", "questions": [{"prompt": "Roberta and Tim are the same age. She is ___ Tim.", "answer": "as old as", "options": ["as old as", "older as", "as older than"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}, {"prompt": "This shirt is ___ small. I can’t move my arms.", "answer": "too", "options": ["too", "enough", "as"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}, {"prompt": "There isn’t ___ water for everyone.", "answer": "enough", "options": ["enough", "too", "as"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}, {"prompt": "He isn’t tall ___ to reach the shelf.", "answer": "enough", "options": ["enough", "too", "as"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}, {"prompt": "Jim’s room is ___ messy as Mark’s.", "answer": "as", "options": ["as", "too", "enough"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}, {"prompt": "We came ___ late and missed the bus.", "answer": "too", "options": ["too", "enough", "as"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}, {"prompt": "I wasn’t listening carefully ___.", "answer": "enough", "options": ["enough", "too", "as"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}, {"prompt": "This box is not as heavy ___ that one.", "answer": "as", "options": ["as", "than", "enough"], "explanation": "Use as + adjective + as for equality, too before an adjective for excess, and enough after an adjective or before a noun."}], "sources": [{"name": "Grammar_ComparisonAdjectives3_18825__sz.pdf", "url": "worksheets/Grammar_ComparisonAdjectives3_18825__sz.pdf"}]}, {"id": "modals-basic", "name": "Modals: ability, rules & advice", "level": "Foundation", "rule": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb.", "questions": [{"prompt": "A penguin ___ fly.", "answer": "can’t", "options": ["can’t", "can", "must"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}, {"prompt": "When he was young, Grandad ___ run twelve kilometres.", "answer": "could", "options": ["could", "can", "must"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}, {"prompt": "You ___ feed your pet every day. (obligation)", "answer": "must", "options": ["must", "mustn’t", "can’t"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}, {"prompt": "You ___ drive fast near a school. (prohibition)", "answer": "mustn’t", "options": ["mustn’t", "must", "should"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}, {"prompt": "It’s late. You ___ go home. (advice)", "answer": "should", "options": ["should", "can’t", "mustn’t"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}, {"prompt": "She can ___ the guitar.", "answer": "play", "options": ["play", "plays", "playing"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}, {"prompt": "The dog hurt its leg and ___ walk.", "answer": "couldn’t", "options": ["couldn’t", "can", "must"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}, {"prompt": "You ___ eat so much chocolate. (advice)", "answer": "shouldn’t", "options": ["shouldn’t", "must", "could"], "explanation": "Use can/could for present/past ability, must for obligation, mustn’t for prohibition, and should for advice. Follow a modal with the base verb."}], "sources": [{"name": "Grammar_Modals1_18832__sz.pdf", "url": "worksheets/Grammar_Modals1_18832__sz.pdf"}, {"name": "Grammar_Modals2_18833__sz.pdf", "url": "worksheets/Grammar_Modals2_18833__sz.pdf"}]}, {"id": "modals-advanced", "name": "Modals: necessity & possibility", "level": "Developing", "rule": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses.", "questions": [{"prompt": "We’re eating out, so I ___ cook.", "answer": "don’t have to", "options": ["don’t have to", "mustn’t", "can’t"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}, {"prompt": "You ___ touch that hot plate!", "answer": "mustn’t", "options": ["mustn’t", "don’t have to", "may"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}, {"prompt": "She ___ go to the party. She hasn’t decided.", "answer": "might", "options": ["might", "must", "has to"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}, {"prompt": "Drivers ___ stop at a red light.", "answer": "must", "options": ["must", "might", "don’t have to"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}, {"prompt": "Helen ___ able to fix her bike.", "answer": "is", "options": ["is", "are", "does"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}, {"prompt": "Will you ___ help me this evening?", "answer": "be able to", "options": ["be able to", "can", "able"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}, {"prompt": "The children got in free. They ___ buy tickets.", "answer": "didn’t have to", "options": ["didn’t have to", "mustn’t", "couldn’t"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}, {"prompt": "You look tired. You ___ go to sleep.", "answer": "should", "options": ["should", "may not", "mustn’t"], "explanation": "Don’t have to means no obligation; mustn’t means prohibition. May/might express possibility. Use be able to for ability in different tenses."}], "sources": [{"name": "Grammar_Modals3_18834__sz.pdf", "url": "worksheets/Grammar_Modals3_18834__sz.pdf"}, {"name": "Grammar_Modals4_18835__sz.pdf", "url": "worksheets/Grammar_Modals4_18835__sz.pdf"}]}, {"id": "passive", "name": "Present & past passive", "level": "Developing", "rule": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action.", "questions": [{"prompt": "English ___ in many countries.", "answer": "is spoken", "options": ["is spoken", "is spoke", "speaks"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}, {"prompt": "These cars ___ in Japan. (present)", "answer": "are made", "options": ["are made", "is made", "are make"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}, {"prompt": "The window ___ yesterday. (break)", "answer": "was broken", "options": ["was broken", "is broke", "was break"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}, {"prompt": "The letters ___ last week. (send)", "answer": "were sent", "options": ["were sent", "was sent", "were send"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}, {"prompt": "This room ___ every day.", "answer": "is cleaned", "options": ["is cleaned", "is clean", "cleans"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}, {"prompt": "The book was ___ by a famous author.", "answer": "written", "options": ["written", "wrote", "write"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}, {"prompt": "___ these cakes made yesterday?", "answer": "Were", "options": ["Were", "Was", "Do"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}, {"prompt": "The bridge ___ in 1990.", "answer": "was built", "options": ["was built", "is build", "was build"], "explanation": "Use am/is/are + past participle for present passive and was/were + past participle for past passive. The subject receives the action."}], "sources": [{"name": "Grammar_PassivePresentPast_1_18837__sz.pdf", "url": "worksheets/Grammar_PassivePresentPast_1_18837__sz.pdf"}, {"name": "Grammar_PassivePresentPast2_18838__sz.pdf", "url": "worksheets/Grammar_PassivePresentPast2_18838__sz.pdf"}]}, {"id": "zero", "name": "Zero conditional", "level": "Developing", "rule": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause.", "questions": [{"prompt": "If you put water in the freezer, it ___.", "answer": "freezes", "options": ["freezes", "will freezing", "freeze"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}, {"prompt": "If you take ice out of the freezer, it ___.", "answer": "melts", "options": ["melts", "melt", "melted"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}, {"prompt": "If you keep a plant in a dark cupboard, it ___.", "answer": "dies", "options": ["dies", "die", "dying"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}, {"prompt": "If you leave milk in the sun, it ___ sour.", "answer": "becomes", "options": ["becomes", "become", "becoming"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}, {"prompt": "If you forget food in the oven, it ___.", "answer": "burns", "options": ["burns", "burn", "burning"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}, {"prompt": "If you are hungry, ___ your packed lunch.", "answer": "eat", "options": ["eat", "eats", "eating"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}, {"prompt": "If it rains, ___ an umbrella.", "answer": "bring", "options": ["bring", "brings", "bringing"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}, {"prompt": "If he ___ too much, he gets fat.", "answer": "eats", "options": ["eats", "eat", "eating"], "explanation": "Use if + present simple, present simple for general truths. An imperative can give an instruction in the result clause."}], "sources": [{"name": "Grammar_ZeroConditional_18877__sz.pdf", "url": "worksheets/Grammar_ZeroConditional_18877__sz.pdf"}]}, {"id": "first", "name": "First conditional", "level": "Developing", "rule": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not.", "questions": [{"prompt": "If it rains, I ___ an umbrella.", "answer": "will take", "options": ["will take", "take yesterday", "taking"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}, {"prompt": "We will buy tickets if we ___ enough money.", "answer": "have", "options": ["have", "will have", "had"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}, {"prompt": "If he ___ to bed soon, he won’t be tired.", "answer": "goes", "options": ["goes", "will go", "go"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}, {"prompt": "If you don’t try, you ___.", "answer": "won’t succeed", "options": ["won’t succeed", "don’t succeeded", "not succeed"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}, {"prompt": "You won’t pass ___ you study harder.", "answer": "unless", "options": ["unless", "if", "when not"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}, {"prompt": "If I ___ the book, I’ll buy it.", "answer": "see", "options": ["see", "will see", "saw"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}, {"prompt": "We will go to the beach if it ___ rain.", "answer": "doesn’t", "options": ["doesn’t", "won’t", "didn’t"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}, {"prompt": "If you touch the hot stove, you ___ yourself.", "answer": "will burn", "options": ["will burn", "burned", "burning"], "explanation": "Use if + present simple and will + base verb for real future possibilities. Unless means if…not."}], "sources": [{"name": "Grammar_FirstConditional1_18826__sz.pdf", "url": "worksheets/Grammar_FirstConditional1_18826__sz.pdf"}, {"name": "Grammar_FirstConditional2_18827__sz.pdf", "url": "worksheets/Grammar_FirstConditional2_18827__sz.pdf"}, {"name": "Grammar_FirstConditional3_18828__sz.pdf", "url": "worksheets/Grammar_FirstConditional3_18828__sz.pdf"}]}, {"id": "second", "name": "Second conditional", "level": "Developing", "rule": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be.", "questions": [{"prompt": "If I won the lottery, I ___ a house.", "answer": "would buy", "options": ["would buy", "will buy", "buy"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}, {"prompt": "If she ___ more time, she would travel.", "answer": "had", "options": ["had", "has", "will have"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}, {"prompt": "If I ___ you, I would apologise.", "answer": "were", "options": ["were", "am", "will be"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}, {"prompt": "We would go out if it ___ raining.", "answer": "weren’t", "options": ["weren’t", "isn’t", "won’t be"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}, {"prompt": "If he studied harder, he ___ better marks.", "answer": "would get", "options": ["would get", "will get", "gets"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}, {"prompt": "What would you do if you ___ a wallet?", "answer": "found", "options": ["found", "find", "will find"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}, {"prompt": "If we lived near the sea, we ___ every day.", "answer": "would swim", "options": ["would swim", "will swim", "swam"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}, {"prompt": "She ___ happier if she had more free time.", "answer": "would be", "options": ["would be", "will be", "is"], "explanation": "Use if + past simple and would + base verb for imaginary or unlikely present/future situations. Were is standard for hypothetical be."}], "sources": [{"name": "Grammar_SecondConditional_18864__sz.pdf", "url": "worksheets/Grammar_SecondConditional_18864__sz.pdf"}]}, {"id": "third", "name": "Third conditional", "level": "Challenge", "rule": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events.", "questions": [{"prompt": "If I had known the answer, I ___ you.", "answer": "would have told", "options": ["would have told", "would tell", "will tell"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}, {"prompt": "If Jim ___ a helmet, he wouldn’t have hurt himself.", "answer": "had worn", "options": ["had worn", "wore", "has worn"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}, {"prompt": "The accident wouldn’t have happened if they ___ my advice.", "answer": "had taken", "options": ["had taken", "took", "have taken"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}, {"prompt": "If we hadn’t left early, we ___ the competition.", "answer": "would have won", "options": ["would have won", "will win", "would win"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}, {"prompt": "If I ___ harder, I would have passed.", "answer": "had studied", "options": ["had studied", "studied", "have studied"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}, {"prompt": "She would have come if you ___ her.", "answer": "had invited", "options": ["had invited", "invite", "have invited"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}, {"prompt": "If he hadn’t driven so fast, he ___ an accident.", "answer": "wouldn’t have had", "options": ["wouldn’t have had", "won’t have", "wouldn’t have"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}, {"prompt": "I would have gone to the party if I ___ at home.", "answer": "hadn’t stayed", "options": ["hadn’t stayed", "didn’t stay", "haven’t stayed"], "explanation": "Use if + had + past participle and would have + past participle for imaginary changes to completed past events."}], "sources": [{"name": "Grammar_ThirdConditional_18872__sz.pdf", "url": "worksheets/Grammar_ThirdConditional_18872__sz.pdf"}]}, {"id": "relative", "name": "Relative clauses", "level": "Developing", "rule": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas.", "questions": [{"prompt": "The policeman ___ gave us directions was helpful.", "answer": "who", "options": ["who", "which", "whose"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}, {"prompt": "The advice ___ you gave me was useful.", "answer": "which", "options": ["which", "who", "where"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}, {"prompt": "That’s the man ___ car is outside.", "answer": "whose", "options": ["whose", "who", "which"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}, {"prompt": "This is the place ___ the accident happened.", "answer": "where", "options": ["where", "which", "whose"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}, {"prompt": "A vegetarian is someone ___ doesn’t eat meat.", "answer": "who", "options": ["who", "which", "where"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}, {"prompt": "That is the bank ___ was robbed.", "answer": "which", "options": ["which", "where", "who"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}, {"prompt": "Tell me about the time ___ you were in Ireland.", "answer": "when", "options": ["when", "whose", "who"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}, {"prompt": "Our TV, ___ we’ve had for years, broke last night.", "answer": "which", "options": ["which", "that", "where"], "explanation": "Use who for people, which for things, whose for possession, where for places and when for times. Non-defining clauses add extra information between commas."}], "sources": [{"name": "Grammar_RelativeClauses_1_18860__sz.pdf", "url": "worksheets/Grammar_RelativeClauses_1_18860__sz.pdf"}, {"name": "Grammar_RelativeClauses_2_18861__sz.pdf", "url": "worksheets/Grammar_RelativeClauses_2_18861__sz.pdf"}]}, {"id": "reported", "name": "Reported speech: statements", "level": "Developing", "rule": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context.", "questions": [{"prompt": "Report with a tense shift: “I live here,” she said. She said she ___ there.", "answer": "lived", "options": ["lived", "lives", "live"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}, {"prompt": "“It will snow,” Mum said. Mum said it ___ snow.", "answer": "would", "options": ["would", "will", "can"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}, {"prompt": "“I can help,” Karen said. Karen said she ___ help.", "answer": "could", "options": ["could", "can", "will"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}, {"prompt": "“They are going,” Tom said. Tom said they ___ going.", "answer": "were", "options": ["were", "are", "is"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}, {"prompt": "Reporting later: “now” usually becomes ___.", "answer": "then", "options": ["then", "tomorrow", "today"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}, {"prompt": "Reporting later: “tomorrow” usually becomes ___.", "answer": "the following day", "options": ["the following day", "yesterday", "the previous day"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}, {"prompt": "“Gran bakes cakes,” Jane said. Jane said Gran ___ cakes.", "answer": "baked", "options": ["baked", "bake", "baking"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}, {"prompt": "Reporting later: “these” usually becomes ___.", "answer": "those", "options": ["those", "this", "here"], "explanation": "With a past reporting verb, tenses commonly shift back: present → past, will → would, can → could. Adjust pronouns and time words to the reporting context."}], "sources": [{"name": "Grammar_ReportedSpeech1_18862__sz.pdf", "url": "worksheets/Grammar_ReportedSpeech1_18862__sz.pdf"}]}, {"id": "reported-commands", "name": "Reported commands & suggestions", "level": "Challenge", "rule": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause.", "questions": [{"prompt": "“Don’t chew gum.” The teacher asked Helen ___ gum.", "answer": "not to chew", "options": ["not to chew", "to not chewing", "don’t chew"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}, {"prompt": "“Catch the ball!” The coach told him ___ it.", "answer": "to catch", "options": ["to catch", "catching", "catch"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}, {"prompt": "“I’ll buy drinks.” Jane offered ___ drinks.", "answer": "to buy", "options": ["to buy", "buying", "buy"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}, {"prompt": "“Don’t wait for me.” She told him ___ for her.", "answer": "not to wait", "options": ["not to wait", "don’t wait", "not waiting"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}, {"prompt": "“Let’s take a taxi.” She suggested ___ a taxi.", "answer": "taking", "options": ["taking", "to take", "take to"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}, {"prompt": "“Stop writing!” The examiner ordered them ___ writing.", "answer": "to stop", "options": ["to stop", "stopping", "stop"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}, {"prompt": "“I’ll be home at six.” Dad promised ___ home at six.", "answer": "to be", "options": ["to be", "being", "be"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}, {"prompt": "“How about a film?” Steve suggested ___ to a film.", "answer": "going", "options": ["going", "to go", "goes"], "explanation": "Use tell/ask + object + to-infinitive for commands, not to for negatives, offer/promise + to, and suggest + -ing or a that-clause."}], "sources": [{"name": "Grammar_ReportedSpeech2_18863__sz.pdf", "url": "worksheets/Grammar_ReportedSpeech2_18863__sz.pdf"}]}, {"id": "compounds", "name": "Some-, any- & no- compounds", "level": "Developing", "rule": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning.", "questions": [{"prompt": "We need ___ good to eat.", "answer": "something", "options": ["something", "anything", "nothing"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}, {"prompt": "We haven’t got ___ to drink.", "answer": "anything", "options": ["anything", "nothing", "something"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}, {"prompt": "Let’s go ___ nice this weekend.", "answer": "somewhere", "options": ["somewhere", "anywhere", "nowhere"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}, {"prompt": "I can’t find my glasses ___.", "answer": "anywhere", "options": ["anywhere", "nowhere", "somewhere"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}, {"prompt": "___ stole my bicycle.", "answer": "Someone", "options": ["Someone", "Anyone", "Anything"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}, {"prompt": "There is ___ in the box. It’s empty.", "answer": "nothing", "options": ["nothing", "anything", "something"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}, {"prompt": "___ answered the phone. I couldn’t reach anybody.", "answer": "No one", "options": ["No one", "Anyone", "Someone"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}, {"prompt": "Is there ___ on the bus?", "answer": "anyone", "options": ["anyone", "no one", "anything"], "explanation": "Use some- compounds in affirmative statements, any- compounds commonly in questions/negatives, and no- compounds with a positive verb for a negative meaning."}], "sources": [{"name": "Grammar_SomeAnyNoCompounds_18865__sz.pdf", "url": "worksheets/Grammar_SomeAnyNoCompounds_18865__sz.pdf"}]}, {"id": "questions", "name": "Subject & object questions", "level": "Developing", "rule": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?", "questions": [{"prompt": "Mary phoned John. Ask about the subject.", "answer": "Who phoned John?", "options": ["Who phoned John?", "Who did phoned John?", "Who did Mary phone?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}, {"prompt": "Mary phoned John. Ask about the object.", "answer": "Who did Mary phone?", "options": ["Who did Mary phone?", "Who phoned John?", "Who did phone Mary?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}, {"prompt": "I played basketball. Ask about the activity.", "answer": "What did you play?", "options": ["What did you play?", "What you played?", "What did you played?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}, {"prompt": "Lisa lives in New York. Make a yes/no question.", "answer": "Does Lisa live in New York?", "options": ["Does Lisa live in New York?", "Does Lisa lives in New York?", "Is Lisa live in New York?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}, {"prompt": "Alex plays basketball. Ask a yes/no question.", "answer": "Does Alex play basketball?", "options": ["Does Alex play basketball?", "Do Alex plays basketball?", "Does Alex plays basketball?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}, {"prompt": "The baby drank all the milk. Ask about the subject.", "answer": "Who drank all the milk?", "options": ["Who drank all the milk?", "Who did drank all the milk?", "Who does drank the milk?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}, {"prompt": "We saw Big Ben. Ask about the object.", "answer": "What did you see?", "options": ["What did you see?", "What you saw?", "What did you saw?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}, {"prompt": "Saul bought the pen. Ask about the subject.", "answer": "Who bought the pen?", "options": ["Who bought the pen?", "Who did bought the pen?", "Who did Saul buy?"], "explanation": "For subject questions, ask who/what + verb without do/does/did. Object questions usually need an auxiliary: Who did you see?"}], "sources": [{"name": "Grammar_SubjectObjectQuestions_18866__sz.pdf", "url": "worksheets/Grammar_SubjectObjectQuestions_18866__sz.pdf"}]}, {"id": "tags", "name": "Tag questions", "level": "Developing", "rule": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?", "questions": [{"prompt": "Lisa is a doctor, ___?", "answer": "isn’t she", "options": ["isn’t she", "doesn’t she", "aren’t she"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}, {"prompt": "I’m a good worker, ___?", "answer": "aren’t I", "options": ["aren’t I", "am I", "do I"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}, {"prompt": "They finished the job, ___?", "answer": "didn’t they", "options": ["didn’t they", "weren’t they", "aren’t they"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}, {"prompt": "Edward won’t buy a present, ___?", "answer": "will he", "options": ["will he", "won’t he", "is he"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}, {"prompt": "The food was delicious, ___?", "answer": "wasn’t it", "options": ["wasn’t it", "didn’t it", "isn’t it"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}, {"prompt": "The dog didn’t eat, ___?", "answer": "did it", "options": ["did it", "does it", "was it"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}, {"prompt": "He doesn’t live in France, ___?", "answer": "does he", "options": ["does he", "is he", "will he"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}, {"prompt": "They weren’t looking, ___?", "answer": "were they", "options": ["were they", "are they", "did they"], "explanation": "A positive statement usually takes a negative tag; a negative statement takes a positive tag. Match the auxiliary and pronoun. I am takes aren’t I?"}], "sources": [{"name": "Grammar_TagQuestions_18867__sz.pdf", "url": "worksheets/Grammar_TagQuestions_18867__sz.pdf"}]}, {"id": "temporals", "name": "Time clauses & temporals", "level": "Developing", "rule": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will.", "questions": [{"prompt": "She will travel abroad when she ___ older.", "answer": "is", "options": ["is", "will be", "was"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}, {"prompt": "As soon as I ___ the top, I’ll take a picture.", "answer": "reach", "options": ["reach", "will reach", "reached"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}, {"prompt": "Wait here until the bus ___.", "answer": "comes", "options": ["comes", "will come", "come"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}, {"prompt": "After you ___ the bill, we can leave.", "answer": "pay", "options": ["pay", "will pay", "paid"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}, {"prompt": "We will have a party when Katie ___ home.", "answer": "comes", "options": ["comes", "will come", "coming"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}, {"prompt": "I will stay until the sun ___ down.", "answer": "goes", "options": ["goes", "will go", "go"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}, {"prompt": "Once I ___ the plans, I can decide.", "answer": "see", "options": ["see", "will see", "saw"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}, {"prompt": "Liz will wait until we ___.", "answer": "arrive", "options": ["arrive", "will arrive", "arrived"], "explanation": "In future time clauses after when, until, after, once, as soon as and by the time, use a present tense rather than will."}], "sources": [{"name": "Grammar_Temporals_18868__sz.pdf", "url": "worksheets/Grammar_Temporals_18868__sz.pdf"}]}, {"id": "used-to", "name": "Used to", "level": "Developing", "rule": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to.", "questions": [{"prompt": "My mother ___ at a clinic, but now she works at a school.", "answer": "used to work", "options": ["used to work", "use to work", "used to working"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}, {"prompt": "People ___ letters. Now they send emails.", "answer": "used to write", "options": ["used to write", "used to wrote", "use to writing"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}, {"prompt": "Did you ___ tennis when you were younger?", "answer": "use to play", "options": ["use to play", "used to play", "use to played"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}, {"prompt": "He didn’t ___ long hair.", "answer": "use to have", "options": ["use to have", "used to have", "used to had"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}, {"prompt": "We ___ in London, but now we live in Madrid.", "answer": "used to live", "options": ["used to live", "use to lived", "used to living"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}, {"prompt": "My grandparents ___ to music on the radio.", "answer": "used to listen", "options": ["used to listen", "used to listened", "use to listening"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}, {"prompt": "People used to ___ by horse and cart.", "answer": "travel", "options": ["travel", "travelled", "travelling"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}, {"prompt": "She ___ wake up early, but now she does.", "answer": "didn’t use to", "options": ["didn’t use to", "didn’t used to", "not used to"], "explanation": "Use used to + base verb for past habits or states that are no longer true. After did/didn’t, use use to."}], "sources": [{"name": "Grammar_UsedTo_18876__sz.pdf", "url": "worksheets/Grammar_UsedTo_18876__sz.pdf"}]}];
